// Which countries have a pack, and how big each is. Bundled into the Mosques
// screen's own chunk (a few KB) rather than fetched, so the screen can say the
// size before it loads anything, and the only request it ever makes is the one
// country file. Regenerated by scripts/build-mosques.mjs.

import index from '../../../public/data/mosques/index.json';
import type { PackIndex } from './pack';

export const MOSQUE_INDEX = index as PackIndex;

export function packInfo(cc: string): { count: number; bytes: number } | null {
  if (!cc) return null;
  return MOSQUE_INDEX.countries[cc.toUpperCase()] ?? null;
}

// Plainer names than Intl's short forms, for reading in a sentence
const NAMES: Record<string, string> = {
  BA: 'Bosnia and Herzegovina',
  CD: 'the Democratic Republic of the Congo',
  CG: 'the Republic of the Congo',
  CC: 'the Cocos (Keeling) Islands',
  HK: 'Hong Kong',
  KN: 'Saint Kitts and Nevis',
  LC: 'Saint Lucia',
  MM: 'Myanmar',
  MO: 'Macao',
  PS: 'Palestine',
  TT: 'Trinidad and Tobago',
};

// Names read with "the" in English ("the list for the United Kingdom")
const WITH_THE = new Set(['AE', 'BS', 'CF', 'CK', 'DO', 'FK', 'FO', 'GB', 'GM', 'IM', 'KM', 'KY', 'MH', 'MV', 'NL', 'PH', 'SB', 'TC', 'US', 'VA', 'VG', 'VI']);

/**
 * The country as it reads mid-sentence: 'the United Kingdom' for 'GB', 'Türkiye'
 * for 'TR' (from the device's own Intl data); the code itself if Intl can't say.
 */
export function countryName(cc: string): string {
  if (!cc) return 'your country';
  const code = cc.toUpperCase();
  if (NAMES[code]) return NAMES[code];
  let name = code;
  try {
    name = new Intl.DisplayNames(['en'], { type: 'region' }).of(code) ?? code;
  } catch {
    return code;
  }
  return WITH_THE.has(code) ? `the ${name}` : name;
}

/** '60 KB', '1.2 MB' */
export function formatBytes(bytes: number): string {
  if (bytes < 1_000_000) return `${Math.max(1, Math.round(bytes / 1000))} KB`;
  return `${(Math.round(bytes / 100_000) / 10).toFixed(1)} MB`;
}
